<?php
namespace Avanik;
defined('ABSPATH') || exit;
final class BookingAdmin {
 public static function register(): void { add_action('admin_menu',[self::class,'menu']); add_action('admin_post_avanik_booking_decision',[self::class,'decision']); }
 public static function menu(): void { add_submenu_page('avanik-providers','Bookings','Bookings','manage_options','avanik-bookings',[self::class,'render']); }
 public static function render(): void { if(!current_user_can('manage_options'))return; global $wpdb; $rows=$wpdb->get_results('SELECT * FROM '.BookingRepository::table_name().' ORDER BY created_at DESC LIMIT 200',ARRAY_A)?:[]; ?><div class="wrap" dir="rtl"><h1>مدیریت رزروها</h1><table class="widefat striped"><thead><tr><th>رزرو</th><th>مسافر</th><th>مقصد</th><th>تاریخ</th><th>مبلغ</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($rows as $b): ?><tr><td><?php echo esc_html($b['booking_id']); ?></td><td><?php echo esc_html($b['passenger_name']); ?></td><td><?php echo esc_html($b['destination']); ?></td><td><?php echo esc_html($b['travel_date']); ?></td><td><?php echo esc_html(number_format((float)$b['total_amount'])); ?></td><td><?php echo esc_html($b['status']); ?></td><td><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('avanik_booking_decision'); ?><input type="hidden" name="action" value="avanik_booking_decision"><input type="hidden" name="booking_id" value="<?php echo esc_attr($b['booking_id']); ?>"><button name="decision" value="confirm" class="button button-primary">تأیید</button> <button name="decision" value="cancel" class="button">لغو</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php }
 public static function decision(): void { if(!current_user_can('manage_options')||!check_admin_referer('avanik_booking_decision'))wp_die('Unauthorized'); $id=sanitize_text_field(wp_unslash($_POST['booking_id']??'')); $d=sanitize_key(wp_unslash($_POST['decision']??'')); $b=BookingRepository::find_by_id($id); if(!$b)wp_die('Booking not found'); $status=$d==='confirm'?Booking::STATUS_CONFIRMED:($d==='cancel'?Booking::STATUS_CANCELLED:$b['status']); global $wpdb; $wpdb->update(BookingRepository::table_name(),['status'=>$status,'updated_at'=>current_time('mysql')],['booking_id'=>$id]); if($status===Booking::STATUS_CONFIRMED)do_action('avanik_booking_confirmed',$id); if($status===Booking::STATUS_CANCELLED)do_action('avanik_booking_cancelled',$id); wp_safe_redirect(admin_url('admin.php?page=avanik-bookings')); exit; }
}